// 获取所有合并后的数据
const allItems = $input.all();

// 根据前面Set节点设置的 'bill_type' 字段拆分数据
const currentMonthItems = allItems.filter(item => item.json.bill_type === 'current');
const lastMonthItems = allItems.filter(item => item.json.bill_type === 'last');

// 辅助函数：清理数字
function parseCost(val) {
  if (typeof val === 'number') return val;
  if (!val) return 0;
  return parseFloat(val.toString().replace(/[^0-9.-]/g, '')) || 0;
}

// 1. 构建上月账单映射表
const lastMonthMap = new Map();

for (const item of lastMonthItems) {
  const row = item.json;
  const resourceName = (row.Resource || '').toString().trim();

  if (resourceName) {
    const currentCost = parseCost(row.CostUSD || row.Cost);
    if (lastMonthMap.has(resourceName)) {
        const existing = lastMonthMap.get(resourceName);
        existing.cost += currentCost;
    } else {
        lastMonthMap.set(resourceName, {
          cost: currentCost,
          fullData: row
        });
    }
  }
}

// 2. 对比分析
const results = [];
const processedResources = new Set();

for (const item of currentMonthItems) {
  const row = item.json;
  const resourceName = (row.Resource || '').toString().trim();

  if (!resourceName) continue;

  const currentCost = parseCost(row.CostUSD || row.Cost);
  const lastMonthData = lastMonthMap.get(resourceName);
  const lastCost = lastMonthData ? lastMonthData.cost : 0;
  const diff = currentCost - lastCost;

  let remark = '';
  if (!lastMonthData) {
    remark = 'New - 新增资源';
  } else if (Math.abs(diff) > 0.01) {
    const percent = lastCost !== 0 ? ((diff / lastCost) * 100).toFixed(2) : '100.00';
    remark = `Cost change: ${diff > 0 ? '+' : ''}${diff.toFixed(2)} USD (${percent}%)`;
  } else {
    remark = 'No change';
  }

  results.push({
    'Resource Group': row.ResourceGroup || row.resourceGroup || '',
    'Resource Name': resourceName,
    'Resource Type': row.ResourceType || row.resourceType || '',
    'Cost (Current)': currentCost.toFixed(2),
    'Cost (Last)': lastCost.toFixed(2),
    'Difference': diff.toFixed(2),
    'Remark': remark
  });

  processedResources.add(resourceName);
}

// 3. 找出已删除资源
for (const [resourceName, data] of lastMonthMap.entries()) {
  if (!processedResources.has(resourceName)) {
    const row = data.fullData;
    results.push({
      'Resource Group': row.ResourceGroup || row.resourceGroup || '',
      'Resource Name': resourceName,
      'Resource Type': row.ResourceType || row.resourceType || '',
      'Cost (Current)': '0.00',
      'Cost (Last)': data.cost.toFixed(2),
      'Difference': (-data.cost).toFixed(2),
      'Remark': 'Deleted - 资源已删除'
    });
  }
}

// 4. 排序
results.sort((a, b) => {
  const getScore = (r) => {
    if (r.Remark.startsWith('New')) return 3;
    if (r.Remark.startsWith('Deleted')) return 2;
    if (r.Remark.startsWith('Cost')) return 1;
    return 0;
  };
  const scoreA = getScore(a);
  const scoreB = getScore(b);
  if (scoreA !== scoreB) return scoreB - scoreA;
  return Math.abs(parseFloat(b.Difference)) - Math.abs(parseFloat(a.Difference));
});

return results.map(r => ({ json: r }));
